def vigenere_encrypt(plaintext, keyword):
    result = ''
    key_len = len(keyword)
    for i, p in enumerate(plaintext):
        if 'A' <= p <= 'Z':
            shift = ord(keyword[i % key_len]) - 65
            encrypted = chr((ord(p) - 65 + shift) % 26 + 65)
            result += encrypted
        else:
            result += p
    return result
